def add_default_fields(apps, schema_editor):
    Project = apps.get_model("db", "Project")
    Field = apps.get_model("db", "ProjectCustomField")
    colors = ("#16A34A", "#2563EB", "#9333EA", "#D97706", "#DC2626", "#475569")
    defaults = (
        ("Stage", ("Concept", "Design", "Copy", "Development", "Testing", "Done")),
        ("Status", ("On Track", "At Risk", "On Hold", "Blocked", "Completed")),
    )
    alias = schema_editor.connection.alias
    for project in Project.objects.using(alias).filter(deleted_at__isnull=True).iterator():
        for index, (name, labels) in enumerate(defaults):
            Field.objects.using(alias).create(
                project_id=project.id,
                workspace_id=project.workspace_id,
                name=name,
                field_type="single_select",
                sort_order=index,
                options=[
                    {"id": str(uuid.uuid4()), "name": label, "color": colors[i]} for i, label in enumerate(labels)
                ],
            )


